(function(){"use strict";var raiz=document.documentElement;if(raiz.getAttribute("data-visual")!=="novo")return;if(!window.matchMedia||!matchMedia("(pointer: fine)").matches)return;if(matchMedia("(prefers-reduced-motion: reduce)").matches)return;var SEL='.mod-card, div[style*="flex: 0 0 250px"] [draggable="true"]';var atual=null,px=0,py=0,agendado=false;function aplicar(){agendado=false;if(!atual)return;var r=atual.getBoundingClientRect();atual.style.setProperty("--mx",Math.round(px-r.left)+"px");atual.style.setProperty("--my",Math.round(py-r.top)+"px")}function limpar(el){if(!el)return;el.style.removeProperty("--mx");el.style.removeProperty("--my")}document.addEventListener("pointermove",(function(e){var alvo=e.target&&e.target.closest?e.target.closest(SEL):null;if(alvo!==atual){limpar(atual);atual=alvo}if(!atual)return;px=e.clientX;py=e.clientY;if(!agendado){agendado=true;requestAnimationFrame(aplicar)}}),{passive:true});document.addEventListener("pointerleave",(function(){limpar(atual);atual=null}),true)})();